mapper.select:
SELECT POSITION_ID, STOCK_GROUP, STOCK_CODE, MARKET_CODE, TOTAL_QTY, AVG_PRICE,
       CLOSE_FLAG, STATE_CODE, LAST_TXN_ID, MODIFY_DATE, CREATE_USER, CREATE_DATE
  FROM TB_S_POSITION
 WHERE 1=1
   AND STOCK_GROUP = #{stockGroup}
   AND CLOSE_FLAG = #{closeFlag}
   AND MARKET_CODE = #{marketCode}
 ORDER BY MODIFY_DATE DESC

SELECT POSITION_ID, STOCK_GROUP, STOCK_CODE, MARKET_CODE, TOTAL_QTY, AVG_PRICE,
       CLOSE_FLAG, STATE_CODE, LAST_TXN_ID, MODIFY_DATE, CREATE_USER, CREATE_DATE
  FROM TB_S_POSITION
 WHERE 1=1
   AND POSITION_ID = #{positionId}
   AND STOCK_GROUP = #{stockGroup}
   AND STOCK_CODE = #{stockCode}
